\operatorname{Sub}_{\operatorname{ER}}
=
\{\theta:\theta_E:E\to E,\theta_R:R\to R,\theta_A:A\to A,\theta_D:D\to D,\theta_I:N_I\to N_I,\theta_V:N_V\to N_V\text{ 是保持种类、保持关系元数的有限支撑函数}\}.

F^0_{\mathcal K,r,i,x}
=\{\bar a:\operatorname{ar}(r)\to N_I:r(\bar a)\in\mathcal I\land
(\bar a(i),x)\in\operatorname{Eq}^{0}_{\mathcal K}\},

\mathsf{Rule}_{eqSym}
=\{((x\approx y),y\approx x):x,y\in N_I\},
\qquad
\mathsf{Rule}_{eqTrans}
=\{((x\approx y,y\approx z),x\approx z):x,y,z\in N_I\}.

\mathsf{Rule}_{eqA}
=
\{((x\approx y,a(x,v)),a(y,v)),((x\approx y,a(y,v)),a(x,v)):a\in A,\ x,y\in N_I,\ v\in N_V\},

\mathsf{Rule}_{cardMin}(\mathcal K)
=
\left\{
\bigl(
(\operatorname{Card}(r,i,m,n),\operatorname{Rel}(r,\kappa),\kappa(i)(x),\operatorname{Complete}(r,i,x)),
\bot_{\mathcal K}
\bigr)
:
\begin{array}{l}
r\in R,\ \operatorname{ar}(r)=k,\ i<k,\ \kappa:k\to E,\ x\in N_I,\\
m,n\in\mathbb N,\ m\le n,\ \exists F\ \operatorname{MinGapCert}_{\operatorname{ER}}(\mathcal K,r,i,x,m,F)
\end{array}
\right\}.
